-- -----------------------------------------------------
-- procedure addPlate
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`addPlate`;

DELIMITER $$
USE `contractiondb2`$$
CREATE procedure `addPlate`(IN _name varchar(45), OUT id int)
BEGIN  
  DECLARE _idLabwareType INT default 0;  
  select name2labwareTypeId(_name) into _idLabwareType;
  IF _idLabwareType=0 THEN 
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addPlate: Failed to get idLabwareType from name';
  END IF;
  insert into labware set idLabwareType = _idlabwaretype;
  SELECT LAST_INSERT_ID() into id;
  IF id=0 THEN 
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addPlate: Failed to get idLabware';
  END IF;
  end$$

DELIMITER ;

