-- -----------------------------------------------------
-- function registerPlate
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`registerPlate`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `registerPlate`(_Name varchar(45), _Device varchar(45) ) RETURNS int DETERMINISTIC
BEGIN
   DECLARE _idEvent, _slot int default 0;
   select idExperiment(_Name) into _idEvent;   
   IF _idEvent is null or _idEvent=0 THEN 
	  select addExperiment(_Name, addPlate('myrplate')) into _idEvent;
   END IF;
   select reserveSlot(_Name, _Device) into _slot;
   RETURN _slot; 
end$$

DELIMITER ;

-- -----------------------------------------------------
-- function registerExperiment
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`registerExperiment`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `registerExperiment`(_Name varchar(45), _labwareTypeName varchar(45)) RETURNS int DETERMINISTIC
BEGIN
  DECLARE _idEvent, _idEventType, _idLabware INT default 0;  
  SELECT idEvent INTO _idEvent from experiment where `name`=_Name;
  IF _idEvent=0 THEN 
    SELECT addPlate(_labwareTypeName)  into _idLabware;
    select addExperiment(_Name, _idLabware) into _idEvent;
  END IF;
 return _idEvent;
end$$

DELIMITER ;

