-- -----------------------------------------------------
-- procedure addExperiment
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`addExperiment`;

DELIMITER $$
USE `contractiondb2`$$
CREATE procedure `addExperiment`(IN exp_name varchar(45), IN _idLabware int,OUT idExp int)
BEGIN
	DECLARE _idEventType  INT default 0;
    #check if labware exists    
    select idLabware into _idLabware from labware where idLabware=_idLabware;
    #
    IF getIdExperiment(exp_name) >0 THEN 
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addExperiment: name exists';
    end if;
    #
    IF _idLabware=0 THEN 
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addExperiment: idLabware does not exist';
	end if;
    call addEvent( _idLabware, getIdEventType('experiment'), 0, exp_name, idExp );
    INSERT INTO experiment(idEvent, `name`, idPerson) VALUES(idExp, exp_name,2);    
end$$

DELIMITER ;

