DELIMITER $$
USE `contractiondb2`$$
CREATE DEFINER=`analyzeMmt`@`134.76.15.%` FUNCTION `hasWells`(_idLabware int) RETURNS int(11)
    DETERMINISTIC
BEGIN
   declare _num int default 0;
   select count(*) into _num from labware where idParent=_idLabware and idParent!=idLabware;
