-- -----------------------------------------------------
-- function storageCapacity
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`storageCapacity`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `storageCapacity`(_Name varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _capacity int default 0;
    select sum(sl.bStorage) into _capacity from location i join location st on st.idParent=i.idLocation join location sl on sl.idParent=st.idLocation  where i.name=_Name and sl.bStorage group by i.name;
	RETURN _capacity;
END$$

