-- -----------------------------------------------------
-- function addWells
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`addWells`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `addWells`(_idLabware int) RETURNS int DETERMINISTIC
BEGIN
  declare _idLabwareType, _rows, _cols int default 0;
  declare _name char(6);
  declare iRow, iCol, iPos int default 0;
  select `rows`, `cols`, w.idLabwareType into _rows, _cols, _idLabwareType
		from labware l join labwaretype using (idLabwareType) join platetype using (idLabwareType) join labwaretype w on (w.idParent=l.idLAbwareType)
        where l.idLabware=_idLabware;   
  #
  while iRow < _rows   do
	set iRow=iRow+1;
    set iCol=0;
	while iCol < _cols	do
		set iCol=iCol+1;
		set iPos=iPos+1;
        set _name=concat(cast(CHAR(64+iRow) as char), cast(iCol as char) );
        insert into labware(idParent, idLabwareType, `row`, `col`, `pos`, `name`) values(_idLabware, _idLabwareType, iRow, iCol, iPos, _name);   
	end while;	
  END WHILE; 
  return iPos;
end$$

DELIMITER ;

-- -----------------------------------------------------
-- function storageFree
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`storageFree`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `storageFree`(_Name varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _capacity int default 0;
    select sum(sl.bStorage-sl.bReserved) into _capacity from location i join location st on st.idParent=i.idLocation join location sl on sl.idParent=st.idLocation  where i.name=_Name and sl.bStorage group by i.name;
	RETURN _capacity;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function reserveSlot
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`reserveSlot`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `reserveSlot`(_Name varchar(45), _Device varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _idStorage, _idEvent, _slot int default 0;
	#
    DECLARE _stackerName, _deviceName varchar(45);
    call getStorageLocation(_Name, _deviceName, _stackerName, _slot);    
    #select getStorageId(_Name) into _idStorage;
    #
    if _slot > 0 and NOT _deviceName = _Device  then
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'reserveSlot: Plate registered on other device';
    elseif _slot is null or _slot = 0 then
		select idExperiment(_Name) into _idEvent;
		select getFreeStorageId(_Device) into _idStorage;        
		update event set idStorage=_idStorage where idEvent=_idEvent;
		update location set bReserved=true where idLocation =_idStorage;
        select getStorageSlot(_Name) into _slot;
    end if;
    #    
    return _slot;
end$$

DELIMITER ;

-- -----------------------------------------------------
-- function getSlot
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`getSlot`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `getSlot`(_Name varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _slot int default 0;
    select refId into _slot from experiment x join event e using (idEvent) join location l on (e.idStorage=l.idLocation);
    return _slot;    
end$$

DELIMITER ;

-- -----------------------------------------------------
-- function unreserveSlot
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`unreserveSlot`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `unreserveSlot`(_slot int, _Device varchar(45)) RETURNS int DETERMINISTIC
BEGIN
declare _idStacker, _bOccupied int default 0;
	select st.idLocation into _idStacker from device d join location st on st.idParent=d.idLocation where d.name=_Device;
    select bOccupied into _bOccupied from Location where refId=_slot and idParent=_idStacker;
    if _bOccupied then
         SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'freeSlot: cant free an occupied slot, empty first';
    else 
		update location set bReserved=false where idRef=_slot and idParent=_idStacker;
	end if;
    return 0;
end$$

DELIMITER ;

