-- -----------------------------------------------------
-- function getFreeSlot
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`getFreeSlot`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `getFreeSlot`(_Device varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _slot, _deviceId int default 0;
    select name2deviceId(_Device) into _deviceId;
    select sl.refId into _slot from location st join location sl on sl.idParent=st.idLocation 
           where st.idParent=_deviceId and sl.bStorage=true and sl.bOccupied=false limit 1;
	if _slot=0 then
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'getFreeSlot: no free slot in device';    
    end if;    
    return _slot;
end$$

DELIMITER ;

