-- -----------------------------------------------------
-- function getStorageSlot
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`getStorageSlot`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `getStorageSlot`(_Name varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _slot int default 0;
    DECLARE _stackerName, _deviceName varchar(45);
    call getStorageLocation(_Name, _deviceName, _stackerName, _slot);
    # select refId into _slot from experiment x join event e using (idEvent) join location l on (e.idStorage=l.idLocation) where x.name=_Name;
    return _slot;    
end$$

