-- -----------------------------------------------------
-- procedure getStorageLocation
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`getStorageLocation`;

DELIMITER $$
USE `contractiondb2`$$
CREATE PROCEDURE `getStorageLocation`(IN _Name varchar(45), OUT _deviceName varchar(45), OUT _stackerName varchar(45), OUT _slot int) 
BEGIN
    select d.name, st.name, sl.refId  into _deviceName, _stackerName, _slot 
    from experiment x join event e using (idEvent) join location sl on (e.idStorage=sl.idLocation) 
    join location st on (sl.idParent=st.idLocation) join device d on (d.idLocation = st.idParent) where x.Name=_Name;
end$$

DELIMITER ;

