-- -----------------------------------------------------
-- procedure unRegisterPlate
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`unRegisterPlate`;

DELIMITER $$
USE `contractiondb2`$$
CREATE PROCEDURE `unRegisterPlate`(IN _Name varchar(45)) 
BEGIN
    DECLARE _idLocation, _idStorage, _idEvent int default 0;
    #
    #
    #   
    select e.idLocation, e.idStorage, e.idEvent  into _idLocation, _idStorage, _idEvent from experiment x join event e using (idEvent)
        join location sl on (e.idStorage=sl.idLocation) where x.Name=_Name;
    #
    # check if plate is in storage slot
    #
    if _idStorage > 0 and _idLocation=_idStorage then
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'unRegisterPlate: Plate currently inside Storage Slot';
	else
      update `event`    set idStorage = NULL where idEvent=_idEvent;
      update `location` set bReserved = 0 where idLocation=_idStorage;
    end if;
end$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure getFreeStorage
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`getFreeStorage`;

DELIMITER $$
USE `contractiondb2`$$
CREATE PROCEDURE `getFreeStorage`(IN _Device varchar(45), OUT _idLocation int, OUT _slot int)
BEGIN
    #
    select sl.refId, sl.idLocation into _slot, _idLocation from location st 
      join location sl on sl.idParent=st.idLocation join device d on (d.idLocation=st.idParent) 
	  where d.name=_Device and sl.bStorage=true and sl.bOccupied=false and sl.bReserved=false  limit 1;
	#
	if _idLocation is null then
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'getFreeStorage: no free slot in device';    
    end if;        
end$$

DELIMITER ;

