-- -----------------------------------------------------
-- function plateCheckIn
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`plateCheckIn`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `plateCheckIn`(_Name varchar(45), _Device varchar(45)) RETURNS int DETERMINISTIC
BEGIN
    DECLARE _idLocation, _idEvent, _idLabware, _idEventType int default 0;
    #
    call experimentData(_Name, _idEvent, _idLabware);
    #
    if _idEvent is null then
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'plateCheckIn: No Such Experiment';
	end if;
    #
    select l.idLocation into _idLocation from location l join device d on (d.idLocation=l.idParent) where l.bTransfer=true and d.name=_Device;
    #
    if _idLocation is null then
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'uplateCheckIn: No Transfer Position on Device';
	end if;
    #   
    update event set idLocation=_idLocation where idEvent=_idEvent;
    #
    select idEventType into _idEventType from eventtype where name='checkin';
    #
    insert into event(idParent, idEventType, idLocation, idLabware) VALUES (_idEvent, _idEventType, _idLocation, _idLabware);
    #
    return _idLocation;
end$$

DELIMITER ;

