-- -----------------------------------------------------
-- function addCompound
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`addCompound`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `addCompound`(_name varchar(45)) RETURNS int DETERMINISTIC
BEGIN
  DECLARE _id INT default 0;  
  select idCompound(_name) into _id;
  IF (_id > 0) THEN 
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addCompound: Compound name already exists';
  ELSE
      insert into compound set name=_name;
      SELECT LAST_INSERT_ID() into _id;
      IF (_id=0) THEN 
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addCompound: Failed to add Compound';
	  END IF;
  END IF;
    
  return _id;
end$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure getCompoundSolutions
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`getCompoundSolutions`;

DELIMITER $$
USE `contractiondb2`$$
CREATE PROCEDURE `getCompoundSolutions`()
BEGIN
 select idCompound, s.idSolution, c.name as compound, s.name as solution, b.name as base, c.mw, sc.concentration, sc.unit  from compound c 
	join solution_compound sc using (idCompound) 
	join solution s using (idSolution)
	join solution b on (s.idParent=b.idSolution)
	order by c.name, s.name, sc.concentration asc;
END$$

