-- -----------------------------------------------------
-- procedure addMeasurement
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`addMeasurement`;

DELIMITER $$
USE `contractiondb2`$$
CREATE procedure `addMeasurement`(IN exp_name varchar(45), IN mea_name varchar(45), OUT idMea int)
BEGIN
	DECLARE idExp, idLabware INT default 0;
    call measurementData(exp_name, mea_name, idMea, idLabware);        
    if idMea>0 then
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addMeasurement: Measurement already exists';
	end if;
    #
    call experimentData(exp_name, idExp, idLabware);   
	#
    if idExp=0 then
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addMeasurement: Experiment does ot exist';
	end if;	
    #    
    call addEvent(  idLabware, getIdEventType('measurement'), idExp, mea_name, idMea);     
    INSERT INTO measurement(idEvent, `name`, idPerson) VALUES(idMea, mea_name, 2);    
    
end$$

