-- -----------------------------------------------------
-- procedure addEvent
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`addEvent`;

DELIMITER $$
USE `contractiondb2`$$
CREATE procedure `addEvent`(IN idLabware int, IN idEventType int, IN idParent int, IN e_name varchar(45), out idEvent int)
BEGIN
	if idParent=0 then
      #indicates self-reference, e.g. experiment
      SET foreign_key_checks = 0;      
    end if;
	insert into event(`idLabware`, `idEventType`, `idParent`, `name`) VALUES (idLabware, idEventType, idParent, e_name);
    SET foreign_key_checks = 1;   
    set idEvent = LAST_INSERT_ID();
end$$

DELIMITER ;

