-- -----------------------------------------------------
-- procedure addForces
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`addForces`;

DELIMITER $$
USE `contractiondb2`$$
CREATE Procedure `addForces`(IN idMea int, IN well_name varchar(45), OUT id int)
BEGIN
	DECLARE _idLabware INT default 0;
    declare mea_name  varchar(45);
    #
    set id=0;    
    #check if labware (well) exists    
    select l.idLabware,  e.name into _idLabware, mea_name
            from labware l join event e on l.idParent=e.idLabware 
            where e.idEvent=idMea and l.name=well_name;
    #
    IF _idLabware =0 THEN 
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addForces: no idLabware (well) for measurement';
    end if;    
    #
    call addEvent(_idLabware, getIdEventType('measurement'), idMea, concat(mea_name,'_',well_name), id);
    #
    IF id=0 THEN 
       SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'addForces: Failed to get idEvent';
	end if;
    #
    INSERT INTO forces(idEvent) VALUES(id); 
end$$

DELIMITER ;

