-- -----------------------------------------------------
-- procedure calcForceStats
-- -----------------------------------------------------

USE `contractiondb2`;
DROP procedure IF EXISTS `contractiondb2`.`calcForceStats`;

DELIMITER $$
USE `contractiondb2`$$
CREATE PROCEDURE `calcForceStats` (IN _idEvent int, OUT nPeak int)
BEGIN
 DECLARE avgHeight, stdHeight, avgRR, stdRR, avgBase float default 0.0; 
 select count(*), avg(height), std(height), avg(RR), std(RR), avg(base) into  nPeak, avgHeight, stdHeight, avgRR, stdRR, avgBase from peak where idEvent=_idEvent;
 #
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'nPeak',         nPeak) on duplicate key update `value`=nPeak;
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'avgHeight', avgHeight) on duplicate key update `value`=avgHeight;
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'stdHeight', stdHeight) on duplicate key update `value`=stdHeight;
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'avgRR',         avgRR) on duplicate key update `value`=avgRR;
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'stdRR',         stdRR) on duplicate key update `value`=stdRR;
 insert into  analysis (`idEvent`, `name`,`value`) VALUES (_idEvent, 'avgBase',     avgBase) on duplicate key update `value`=avgBase;
  
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function runCalcStats
-- -----------------------------------------------------

USE `contractiondb2`;
DROP function IF EXISTS `contractiondb2`.`runCalcStats`;

DELIMITER $$
USE `contractiondb2`$$
CREATE FUNCTION `runCalcStats`(_idEvent int) RETURNS int DETERMINISTIC
BEGIN
  DECLARE nPEak int default 0;
  call calcForceStats(_idEvent, nPeak);
  return nPeak;
END$$

DELIMITER ;

