-- -----------------------------------------------------
-- View `contractiondb2`.`_vPeak`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`_vPeak`;
DROP VIEW IF EXISTS `contractiondb2`.`_vPeak` ;
USE `contractiondb2`;
create or replace view _vPeak as
select p.idPeak, p.idEvent as idForces, p.idPrevious, ex.name as experiment, m.name as measurement, l.name as well, 
round(p.t4-p.t1*m.resolutionTime,1) as duration, round(p.RR*m.resolutionTime,1) as RR,
p.time, p.base, p.height, et.frequency as 'stimulation'
from peak p join `event` e using (idEvent) 
join labware l using (idLabware)
left join eventtype et using (idEventType)
join measurement m on e.idParent=m.idEvent 
join `event` em on (m.idEvent=em.idEvent)
join experiment ex on  em.idParent=ex.idEvent   


order by ex.name, m.name, l.name, p.frame;

-- -----------------------------------------------------
-- View `contractiondb2`.`_vMeasurement`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`_vMeasurement`;
DROP VIEW IF EXISTS `contractiondb2`.`_vMeasurement` ;
USE `contractiondb2`;
create or replace view _vMeasurement as 
select e.`name` as `experiment`, m.`name` as `measurement`, w.name as `well`, 
round(avg(p.height),2) as `height`, round(avg(p.RR)*m.resolutionTime,1) as `RR`,
round(avg(p.t4-p.t1)*m.resolutionTime,1) as `duration`

from `event` ex
join `event` em on (em.idParent=ex.idEvent)
join `event` ew on (ew.idParent=em.idEvent)
join experiment e on (e.idEvent=ex.idEvent)
join measurement m on (em.idEvent=m.idEvent)
join labware w on (ew.idLabware=w.idLabware)
left join peak p on (p.idEvent=ew.idEvent)

where w.idParent!=w.idLabware
group by e.name, m.name, w.name, ex.idEvent, em.idEvent, ew.idLabware, m.resolutionTime
order by e.name, m.name, w.name;

-- -----------------------------------------------------
-- View `contractiondb2`.`vexperiment`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`vexperiment`;
DROP VIEW IF EXISTS `contractiondb2`.`vexperiment` ;
USE `contractiondb2`;
create or replace view vexperiment as
select e.idEvent as idExperiment, e.name as experiment, p.name as plate, w.name as well
from event join experiment e using (idEvent)
join labware p using (idLabware)
join labwaretype lt using (idLabwareType)
join labware w on w.idParent=p.idLabware
where w.idlabware!=p.idLabware;

-- -----------------------------------------------------
-- View `contractiondb2`.`_vEhm`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`_vEhm`;
DROP VIEW IF EXISTS `contractiondb2`.`_vEhm` ;
USE `contractiondb2`;
create or replace view `_vEhm` as
Select e.idEvent as idEhm, ex.name as `experiment`, l.name as `well`, ee.date as  `cast` 
from ehm e
join event ee using (idEvent)
join labware l using (idLabware)
join experiment ex on ee.idParent=ex.idEvent;

-- -----------------------------------------------------
-- View `contractiondb2`.`_vForces`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`_vForces`;
DROP VIEW IF EXISTS `contractiondb2`.`_vForces` ;
USE `contractiondb2`;
CREATE   or replace  VIEW `_vForces` 
AS     SELECT          `e`.`name` AS `experiment`, e.idEvent as idExperiment,
                     `m`.`name` AS `measurement`, m.idEvent as idMeasurement, 
                     `w`.`name` AS `well`, f.idEvent as 'idForces', f.twitchForce,
					ROUND(AVG(`p`.`height`), 2) AS `height`,         ROUND((AVG(`p`.`RR`) * `m`.`resolutionTime`),                 1) AS `RR`,
					ROUND((AVG((`p`.`t4` - `p`.`t1`)) * `m`.`resolutionTime`),                 1) AS `duration`    
FROM         (((((((`event` `ex` 
        JOIN `event` `em` ON ((`em`.`idParent` = `ex`.`idEvent`)))         
		JOIN `event` `ew` ON ((`ew`.`idParent` = `em`.`idEvent`)))         
		JOIN `experiment` `e` ON ((`e`.`idEvent` = `ex`.`idEvent`)))         
        JOIN `measurement` `m` ON ((`em`.`idEvent` = `m`.`idEvent`)))         
        JOIN `labware` `w` ON ((`ew`.`idLabware` = `w`.`idLabware`)))
        LEFT JOIN `forces` `f` ON ((`f`.`idEvent` = `ew`.`idEvent`)))
        LEFT JOIN `peak` `p` ON ((`p`.`idEvent` = `ew`.`idEvent`)))
WHERE         (`w`.`idParent` <> `w`.`idLabware`)     
GROUP BY `ex`.`idEvent` , `em`.`idEvent` , `ew`.`idLabware`, e.name, e.idEvent, m.name, w.name, e.idEvent, m.idEvent, f.idEvent, f.twitchForce, m.resolutionTime
ORDER BY `e`.`name` , `m`.`name` , `w`.`name`;

-- -----------------------------------------------------
-- View `contractiondb2`.`vStorage`
-- -----------------------------------------------------
DROP TABLE IF EXISTS `contractiondb2`.`vStorage`;
DROP VIEW IF EXISTS `contractiondb2`.`vStorage` ;
USE `contractiondb2`;
create or replace view vStorage as select d.name as `device`, sl.refId as `slot`, sl.bOccupied, sl.bReserved, x.name 
from device d join location i using (idLocation)
join location st on st.idParent=i.idLocation 
join location sl on sl.idParent=st.idLocation 
left join event e on e.idStorage=sl.idLocation 
left join experiment x using (idEvent)
where sl.bStorage=true;
USE `contractiondb2`;

DELIMITER $$

USE `contractiondb2`$$
DROP TRIGGER IF EXISTS `contractiondb2`.`labware_BEFORE_INSERT` $$
USE `contractiondb2`$$
CREATE DEFINER = CURRENT_USER TRIGGER `contractiondb2`.`labware_BEFORE_INSERT` BEFORE INSERT ON `labware` FOR EACH ROW
BEGIN
declare _idLabwareType int default 0;
   IF NEW.idLabwareType=0 THEN
     select idLabwareType into _idLabwareType from labwaretype where `name`=NEW.type;
     SET NEW.idLabwareType=_idLabwareType;
   end if;
   IF NEW.idLabwareType=0 THEN
     SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'BEFORE_INSERT: Plate Type not Found';
   end if;
   
END$$


USE `contractiondb2`$$
DROP TRIGGER IF EXISTS `contractiondb2`.`Event_BEFORE_INSERT` $$
USE `contractiondb2`$$
#CREATE DEFINER = CURRENT_USER TRIGGER Event_BEFORE_INSERT BEFORE INSERT ON `event` FOR EACH ROW
#BEGIN
#  if (select count(*) from event join experiment using (idEvent) where NEW.idLabware=idLabware and NEW.idEventType=idEventType) > 0 THEN
#    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event_BEFORE_INSERT:  Experiment exists on this Plate';      
#  end if; 
# SET NEW.modified = CURRENT_TIMESTAMP;
#END$$


USE `contractiondb2`$$
DROP TRIGGER IF EXISTS `contractiondb2`.`Event_BEFORE_UPDATE` $$
USE `contractiondb2`$$
CREATE DEFINER = CURRENT_USER TRIGGER `Event_BEFORE_UPDATE` BEFORE UPDATE ON `event` FOR EACH ROW
BEGIN
 SET NEW.modified = CURRENT_TIMESTAMP;
END$$


